edits.before:
LaunchedEffect(danmakuManager, viewModel) {
    danmakuManager.setOnDanmakuClickListener { text, dmid, userHash, isSelf ->
        android.util.Log.d("VideoDetailScreen", "👆 Danmaku clicked: $text")
        viewModel.showDanmakuMenu(dmid, text, userHash, isSelf)
    }
}

edits.after:
androidx.compose.runtime.DisposableEffect(danmakuManager, viewModel, holderPlatform) {
    val clickLease = holderPlatform.acquireDanmakuClickListener { text, dmid, userHash, isSelf ->
        android.util.Log.d("VideoDetailScreen", "👆 Danmaku clicked: $text")
        viewModel.showDanmakuMenu(dmid, text, userHash, isSelf)
    }
    onDispose { clickLease.close() }
}

edits.before:
val collapsedSystemBarInset = remember(view, configuration.densityDpi) {
    val rootInsetPx = ViewCompat.getRootWindowInsets(view)
        ?.getInsetsIgnoringVisibility(
            WindowInsetsCompat.Type.statusBars() or
                WindowInsetsCompat.Type.displayCutout()
        )
        ?.top
        ?: 0
    val statusBarResourceId = context.resources.getIdentifier(
        "status_bar_height",
        "dimen",
        "android",
    )
    val resourceInsetPx = if (statusBarResourceId != 0) {
        context.resources.getDimensionPixelSize(statusBarResourceId)
    } else {
        0
    }
    with(insetDensity) { maxOf(rootInsetPx, resourceInsetPx).toDp() }
}

edits.after:
scope.launch {
    if (platform.accounts.setPlaybackAccountMid(vipCandidate.mid)) {
        kotlinx.coroutines.currentCoroutineContext().ensureActive()
        if (platform.isCurrent()) {
            platform.showFeedback("已使用「${vipCandidate.name.ifBlank { "UID ${vipCandidate.mid}" }}」的大会员播放")
            viewModel.retry()
        }
    }
}
